import numpy as np
from lib_geom import quat_from_axes

PAD_OFFSET_M = 0.1501  # jaw contact centre along approach from link6

def flange_for(pad_xyz, approach, jaw):
    a = np.asarray(approach, float); a = a/np.linalg.norm(a)
    p = np.asarray(pad_xyz, float) - PAD_OFFSET_M*a
    q = quat_from_axes(a, jaw)
    return list(np.round(p, 6)) + list(np.round(q, 6))

def probe(arm, poses, interaction="precision"):
    from robot import query
    r = query("reach_check", arm=arm, poses=poses, interaction=interaction)
    return r.get("results", [])
